import{_ as r,c as o,o as a,aj as n}from"./chunks/framework.Id7s26SP.js";const u=JSON.parse('{"title":"Interface: FunctionRunError","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/FunctionRunError.md","filePath":"reference/js-bao-wss-client/api/interfaces/FunctionRunError.md"}'),t={name:"reference/js-bao-wss-client/api/interfaces/FunctionRunError.md"};function s(i,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / FunctionRunError</p><h1 id="interface-functionrunerror" tabindex="-1">Interface: FunctionRunError <a class="header-anchor" href="#interface-functionrunerror" aria-label="Permalink to “Interface: FunctionRunError”">​</a></h1><p>Why a function run failed. The ONE structured error on this surface.</p><p>The workflow type carries two fields for this — a raw <code>error</code> passthrough and a normalized <code>failure</code> beside it — because principle 5 forbade moving a published value. This is a new type, so it has one.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="code" tabindex="-1">code? <a class="header-anchor" href="#code" aria-label="Permalink to “code?”">​</a></h3><blockquote><p><code>optional</code> <strong>code?</strong>: <a href="./../type-aliases/FunctionRunErrorCode.html"><code>FunctionRunErrorCode</code></a></p></blockquote><p>The platform&#39;s classification, when it made one. The same value as <a href="./FunctionRun.html#errorcode">FunctionRun.errorCode</a>, lifted here so a caller reading the error does not have to also hold the run block.</p><hr><h3 id="details" tabindex="-1">details? <a class="header-anchor" href="#details" aria-label="Permalink to “details?”">​</a></h3><blockquote><p><code>optional</code> <strong>details?</strong>: <code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;</p></blockquote><p>Any remaining wire keys, key for key.</p><hr><h3 id="message" tabindex="-1">message <a class="header-anchor" href="#message" aria-label="Permalink to “message”">​</a></h3><blockquote><p><strong>message</strong>: <code>string</code></p></blockquote><p>What went wrong. Always present: an error the client publishes is one it can describe. A platform refusal leads its message with its code.</p><hr><h3 id="name" tabindex="-1">name? <a class="header-anchor" href="#name" aria-label="Permalink to “name?”">​</a></h3><blockquote><p><code>optional</code> <strong>name?</strong>: <code>string</code></p></blockquote><p>The thrown error&#39;s own NAME, when the engine preserved one (<code>Error</code>, <code>TypeError</code>, a tenant&#39;s own class). Absent for a failure read off the persisted row — the platform keeps only the message there and labels it <code>WorkflowError</code>, which is a placeholder and not a name, so this client drops it — and absent whenever the engine dropped the name. Never the code: read <a href="#code">code</a> for that.</p>',22)])])}const f=r(t,[["render",s]]);export{u as __pageData,f as default};
